async fn forget_saved_session_owned<R: tauri::Runtime>(
    handle: tauri::AppHandle<R>,
    app: AppState,
    settings: crate::settings::SettingsState,
    generation: u64,
    username: REDACTED,
) -> CommandResult<()> {
    let auth = app.auth_operation.clone().lock_owned().await;
