    let sync_all = policy.history
        && policy.attachments
        && policy.profile
        && policy.appearance
        && policy.contacts;
    let mut value = if let Some(snapshot) = runtime.handle().account_access_snapshot() {
        let value = AccountLogin::decode(&snapshot)?;
        if value.sync_all == sync_all {
